#!/usr/bin/env python3
"""Patch 26.09.2026: update_sentiment.py laeuft im Nightly nur noch woechentlich.

Warum: Kostenbremse (Entscheidung Paul). Google Places + Gemini fuer 27 Marken
liefen taeglich; der woechentliche Montagslauf des Preis-Workflows reicht.
Idempotent ueber die Signatur '_nur_woechentlich_ueberspringen' im NEUEN Text.
"""
import base64, sys
PFAD = "scripts/update_sentiment.py"
SIGNATUR = "def _nur_woechentlich_ueberspringen():"
PAARE = [("ZGVmIG1haW4oKToKICAgIHRvZGF5ID0gZGF0ZXRpbWUubm93KHRpbWV6b25lLnV0Yykuc3RyZnRpbWUoIiVZLSVtLSVkIikK", "")]

s = open(PFAD, "r", encoding="utf-8").read()
if SIGNATUR in s:
    print("SKIP: bereits angewendet"); sys.exit(0)
for a64, n64 in PAARE:
    a = base64.b64decode(a64).decode("utf-8"); n = base64.b64decode(n64).decode("utf-8")
    anzahl = s.count(a)
    if anzahl != 1:
        print(f"ABBRUCH: Ankertext kommt {anzahl}x vor statt 1x - nichts geaendert."); sys.exit(1)
    s = s.replace(a, n)
open(PFAD, "w", encoding="utf-8").write(s)
print("OK: Kostenbremse in update_sentiment.py eingebaut")
